states.326668621bcf:
{
 "belge": "Ardıç Portföy Yönetimi — Hisse Masası Günlük KAP Takip Dökümü",
 "tarih": "2026-07-09 (Perşembe)",
 "hazirlayan": "Kıvanç Sarıgül, araştırma asistanı",
 "makro_gundem": "Bugün yurt içinde önemli veri yok. Haftaya TCMB piyasa katılımcıları anketi açıklanacak; PPK toplantısı 23 Temmuz'da. Dolar/TL sabah 41,92 seviyesinde, BIST 100 açılışta yatay. ABD'de akşam saatlerinde haftalık işsizlik başvuruları takip edilecek. Brent petrol 71 dolar civarında. Sabah toplantısında kâr realizasyonu ihtimali konuşuldu; masanın genel duruşunda değişiklik yok.",
 "portfoy_notu": "Hisse fonumuzda SRCEN %4,2, KSTEX %1,1, AKOYS %2,7, YMNIN %0,8 ağırlığa sahiptir; PLTUN, GRSGD, ERDMD ve DRKHV portföyde bulunmuyor. Risk komitesi tek hisse ağırlık limitini %10 olarak teyit etti. Likidite tamponu %6,5 seviyesinde. Ay sonu yeniden dengelemesi 30 Temmuz'da yapılacak. Fonun yılbaşından bu yana getirisi %18,4, karşılaştırma ölçütü olan BIST 100 getiri endeksinin aynı dönemdeki getirisi %16,9'dur. Son çeyrekte en yüksek katkıyı sanayi ve enerji hisseleri, en düşük katkıyı ise perakende ve ulaştırma hisseleri yaptı. Haziran ayında fona net 214 milyon TL giriş oldu; girişin büyük bölümü bireysel emeklilik fonlarından ve iki kurumsal müşteriden geldi. Temmuz ayının ilk haftasında ise net akım yatay seyretti. Nakit tarafında ters repo ve para piyasası fonu ağırlıkları değiştirilmedi; vadeli işlemler piyasasında açık pozisyon bulunmuyor.",
 "kap_akisi": [
  {
   "saat": "08:47",
   "sirket": "Sarıçam Enerji Üretim A.Ş. (SRCEN)",
   "konu": "Pay Geri Alım İşlemlerine İlişkin Bildirim",
   "ozet": "Genel kurulda onaylanan geri alım programı kapsamında 08.07.2026 tarihinde Borsa İstanbul'da 150.000 adet pay, 52,10 – 52,80 TL fiyat aralığında, ortalama 52,40 TL'den geri alınmıştır. Bu işlemle birlikte program kapsamında geri alınan toplam pay adedi 2.350.000'e ulaşmış olup bu payların sermayeye oranı %0,94'tür."
  },
  {
   "saat": "09:05",
   "sirket": "Kestel Tekstil ve Konfeksiyon A.Ş. (KSTEX)",
   "konu": "Sermaye Artırımı - Azami",
   "ozet": "Şirketimizin 400.000.000 TL olan çıkarılmış sermayesinin, tamamı nakden karşılanmak suretiyle %100 oranında bedelli artırılarak 800.000.000 TL'ye çıkarılmasına ilişkin izahname SPK tarafından onaylanmıştır. Yeni pay alma (rüçhan) hakkı kullanım fiyatı 1 TL nominal değerli pay için 1,00 TL olup hak kullanım süresi 15 gündür. Elde edilecek fonun yaklaşık %70'i finansal borçların kapatılmasında, kalanı işletme sermayesinde kullanılacaktır."
  },
  {
   "saat": "09:30",
   "sirket": "Yamanlar İnşaat ve Taahhüt A.Ş. (YMNIN)",
   "konu": "Yeni İş İlişkisi",
   "ozet": "İzmir Bayraklı'da 412 konut ve 38 ticari üniteden oluşan proje için yüklenici olarak 2,1 milyar TL + KDV bedelli sözleşme imzalanmıştır. Projenin 30 ayda tamamlanması planlanmaktadır."
  },
  {
